using System.ComponentModel.DataAnnotations;
namespace HoaSap.BLL.Workshops;

public sealed record WorkshopListDto(Guid Id, string Code, string Name, string? ShortName, string? Category, decimal BasePrice, int Duration, int MaxCapacity, string? Description, bool IsFeatured, bool IsActive);
public sealed record WorkshopDto(Guid Id, string Code, string Name, string? ShortName, string? Category, decimal BasePrice, int Duration, int MaxCapacity, string? Description, string? LeadContent, string? GoalsJson, string? IncludesJson, string? ForWho, bool IsFeatured, bool IsActive, Guid? InstructorId);
public sealed class WorkshopUpsertDto { [Required, MaxLength(50)] public string Code { get; set; } = ""; [Required, MaxLength(200)] public string Name { get; set; } = ""; [MaxLength(100)] public string? ShortName { get; set; } [MaxLength(100)] public string? Category { get; set; } [Range(0, 1000000000)] public decimal BasePrice { get; set; } [Range(1, 100000)] public int Duration { get; set; } [Range(1, 100000)] public int MaxCapacity { get; set; } public string? Description { get; set; } public string? LeadContent { get; set; } public string? GoalsJson { get; set; } public string? IncludesJson { get; set; } public string? ForWho { get; set; } public bool IsFeatured { get; set; } = false; public bool IsActive { get; set; } = true; public Guid? InstructorId { get; set; } }
public sealed record SessionDto(Guid Id, Guid WorkshopId, DateTime SessionDate, TimeSpan StartTime, TimeSpan EndTime, string Location, int Capacity, int BookedSlots, string SessionStatus);
public sealed class SessionUpsertDto { public DateTime SessionDate { get; set; } [Required] public TimeSpan StartTime { get; set; } [Required] public TimeSpan EndTime { get; set; } [Required, MaxLength(300)] public string Location { get; set; } = ""; [Range(1, 100000)] public int Capacity { get; set; } }
public sealed class BookingRequest { [Range(1, 100)] public int TicketCount { get; set; } [Required, MaxLength(160)] public string CustomerName { get; set; } = ""; [Required, Phone] public string CustomerPhone { get; set; } = ""; [EmailAddress, MaxLength(200)] public string? CustomerEmail { get; set; } [MaxLength(100)] public string? IdempotencyKey { get; set; } }
public sealed record BookingDto(Guid Id, Guid SessionId, string BookingCode, string CustomerName, int TicketCount, decimal TotalAmount, decimal DepositAmount, decimal RemainingAmount, string BookingStatus, DateTime HoldExpiresAt, DateTime? CheckedInAt, DateTime CreatedAt, decimal PendingVerificationAmount, string? PendingTransactionCode);
public sealed record TicketDto(Guid BookingId, string BookingCode, string CustomerName, int TicketCount, string WorkshopName, DateTime SessionStartUtc, DateTime SessionEndUtc, string Location, string BookingStatus, DateTime? CheckedInAt, bool Issued, string? QrPngBase64, string? CheckInUrl);
public sealed record TicketScanDto(Guid BookingId, string BookingCode, string CustomerName, int TicketCount, string WorkshopName, Guid SessionId, DateTime SessionStartUtc, DateTime SessionEndUtc, string Location, string BookingStatus, DateTime? CheckedInAt, bool FullyPaid, bool CanCheckIn, string? Reason);
public sealed class ManualPaymentRequest { [Required, MaxLength(100)] public string TransactionCode { get; set; } = ""; [Required] public string PaymentMethod { get; set; } = ""; [Range(0.01, 1000000000000d)] public decimal Amount { get; set; } }
public sealed class ConfirmPaymentRequest { [Required, MaxLength(100)] public string TransactionCode { get; set; } = ""; }
public sealed class RefundRequest { [Range(0.01, double.MaxValue)] public decimal Amount { get; set; } [Required, MaxLength(500)] public string Reason { get; set; } = ""; }
public sealed record VnPayCheckoutDto(Guid BookingId, string TxnRef, int Amount, string PaymentUrl, DateTime ExpiresAtUtc);
public sealed record VnPaySyncDto(string BookingStatus, decimal RemainingAmount, bool Paid, decimal AwaitingAmount, string LastResult);
public sealed class VnPayReturnRequest { [Required] public string Query { get; set; } = ""; }
